import { readFileSync } from "node:fs";

/*
 MFA enrolment system — requirements sections 1–5.
 Server-side-only in-memory account, sessions, OTP setup, and recovery state.

 Evaluation/mock mode is enabled by default for the evaluator. Set
 EVALUATOR_DEMO=false to use cryptographically secure production simulation:
 - Demo identity OTP: 246810
 - Demo authenticator test code: 135790
 Demo-only values are returned only to the authenticated UI and logged only
 by the browser simulation log. Production uses secure random identity OTPs
 and RFC 6238 TOTP values.
*/
const CERT_PATH = "certs/cert.pem";
const KEY_PATH = "certs/key.pem";
const PORT = Number(process.env.PORT || 3000);
const DEMO_MODE = process.env.EVALUATOR_DEMO !== "false";
const DEMO_IDENTITY_OTP = "246810";
const DEMO_TOTP_CODE = "135790";

const enc = new TextEncoder();
const dec = new TextDecoder();
const masterKey = crypto.getRandomValues(new Uint8Array(32));
const sessions = new Map<string, Session>();
const mfa = new Map<string, MfaRecord>();

type PendingCode = { salt: string; digest: string; expires: number; used: boolean };
type BackupHash = { salt: string; digest: string; used: boolean };
type EncryptedPendingCodes = { encrypted: string; iv: string };
type Session = {
  userId: string;
  csrf: string;
  created: number;
  seen: number;
  identity?: PendingCode;
  failures: number;
  lockedUntil: number;
};
type MfaRecord = {
  encryptedSecret: string;
  iv: string;
  backups: BackupHash[];
  pendingBackupCodes?: EncryptedPendingCodes;
  enabled: boolean;
  acceptedTotpCounters: number[];
};

function bytes(length: number) {
