    const n = alphabet.indexOf(character);
    if (n < 0) throw new Error("Invalid setup key");
    held = (held << 5) | n;
    bits += 5;
    if (bits >= 8) {
      output.push((held >>> (bits - 8)) & 255);
      bits -= 8;
    }
