  /*
   Demo mode is deliberately separate from production mode. Its fixed test code
   is still tracked against the current time step to prevent replay in a step.
  */
  if (DEMO_MODE) {
    if (record.acceptedTotpCounters.includes(nowCounter)) return null;
    return fixedEqual(code, DEMO_TOTP_CODE) ? nowCounter : null;
  }

  const secret = await decryptSecret(record);
  for (const counter of [nowCounter - 1, nowCounter, nowCounter + 1]) {
    if (record.acceptedTotpCounters.includes(counter)) continue;
    if (fixedEqual(code, await totpAtCounter(secret, counter))) return counter;
