    authenticatorSetupView();
  } catch (error) {
    showError(error);
  }
}

function authenticatorSetupView() {
  if (!setup) return restoreAuthenticatorView();
  const secret = setup.secret;
  const uri = setup.provisioningUri;

  showStep(
    "Step 3 of 5 · Add authenticator",
