  x.fillStyle="#fff"; x.fillRect(0,0,171,171); x.fillStyle="#111";
  for(let y=0;y<n;y++) for(let z=0;z<n;z++) { seed=(seed*1664525+1013904223)>>>0; if(seed&0x80000000) x.fillRect(z*size,y*size,size+1,size+1); }
